package testUtil

import chisel3._
import chisel3.simulator.EphemeralSimulator._

class PrintHelper(){
    def printMatrix(mat: Array[Int], n: Int): Unit = {
        println("[")
        for (i <- 0 until n) {
            var _row = ""
            for (j <- 0 until n) {
                _row += mat(i * n + j).toString() + ", "
            }
            println("[" + _row + "],")
        }
        println("]")
    }

    def printVector(vec: Array[Int], n: Int): Unit = {
        var _row = ""
        for (i <- 0 until n) {
            _row += vec(i).toString() + ", "
        }
        println("[" + _row + "],")
    }

    def printMatrixChisel(mat: chisel3.Vec[chisel3.SInt], n: Int): Unit = {
        println("[")
        for (i <- 0 until n) {
            var _row = ""
            for (j <- 0 until n) {
                _row += mat(i * n + j).peek().litValue.toString() + ", "
            }
            println("[" + _row + "],")
        }
        println("]")
    }

    def printVectorChisel(vec: chisel3.Vec[chisel3.SInt], n: Int): Unit = {
        var _row = ""
        for (i <- 0 until n) {
            _row += vec(i).peek().litValue.toString() + ", "
        }
        println("[" + _row + "]")
    }
}

val buffer_a = (1 until n map(x => Module(new Pipe(SInt(nbits.W), x))))
val buffer_b = (1 until n map(x => Module(new Pipe(SInt(nbits.W), x))))
// Per-lane accum pipes: replaces Pipe(Vec(n,...), 2n-1) which produces a
// single valid FF with fanout=n*(2n-1) (1025 for n=32) spanning the full
// die and violating timing at 250 MHz.  One Pipe per lane gives each lane
// its own independent valid chain (fanout ≤ 2n-1 = 63), allowing Vivado
// to place each replica near its consumers and cut net delay by ~6x.
val buffer_accum = (0 until n map(x => Module(new Pipe(SInt(accum_nbits.W), 2 * n - 1))))

// TODO: replace the enqueue as io port
for (i <- 0 until n - 1) {
    buffer_a(i).io.enq.valid := true.B
    buffer_b(i).io.enq.valid := true.B
}
for (i <- 0 until n) {
    buffer_accum(i).io.enq.valid := true.B
    buffer_accum(i).io.enq.bits  := io.reg_accum_in(i)
    io.reg_accum_out(i)          := buffer_accum(i).io.deq.bits
}

// chainsaw layout
for (i <- 0 until n) {
    if (i == 0) {
        io.reg_a_out(i) := io.reg_a_in(i)
        io.reg_b_out(i) := io.reg_b_in(i)
    } else {
        io.reg_a_out(i) := buffer_a(i-1).io.deq.bits
        io.reg_b_out(i) := buffer_b(i-1).io.deq.bits

        buffer_a(i-1).io.enq.bits := io.reg_a_in(i)
        buffer_b(i-1).io.enq.bits := io.reg_b_in(i)
    }
}
